      SUBROUTINE PRINT1(LABEL,NWORD,DATA,VARY,INDEX)CC     PRINT DATA FOR ONE ELEMENTCC---------------------------------------------------------------------      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDCHAR.CIN'C ----------------------------------------------------------------------      CHARACTER*1     CHAR(15), CHARS(12), CHART(30), ILIM, ILIMO      CHARACTER*8     LABEL      INTEGER         VARY(100), NV(37), NVT(5)      EQUIVALENCE     (CHAR(1), CHARS(1), CHART(1)), (NTYPE,FTYPE),     1                (DATA2,IDATA2), (DATA3,IDATA3)      REAL            DATA(30)      DATA NV         /6,-1, 1,-1,-1, 0, 6, 6, 0, 1,     1                 0,15, 0, 6, 0, 2, 0, 2, 2, 1,     2                 0, 0, 0, 0, 2, 1, 6,-1,-1, 1,     3                 0, 0, 0,-1,-1,-1, 0/      DATA NVT        /1,1,1,1,0/C      ILIM = QUOTE      IF (LABEL .EQ. BLANK) ILIM = BLANK      IF (INDEX .NE. 1) ILIMO = BLANK      IF (INDEX .EQ. 1) ILIMO = ASTERC      FTYPE = DATA(1)      KTYPE = IABS(NTYPE)      IF (KTYPE .EQ. 0) THEN        WRITE (NOUT,970) ILIMO, ILIM, LABEL, ILIM,     1                   (DATA(J), J = 2, NWORD), PARENC        GO TO 100      ENDIF      IF (KTYPE .EQ. 16 .AND. DATA(2) .LT. 0.0) THEN        WRITE (NOUT,980) ILIMO, NTYPE, ILIM, LABEL, ILIM,     1                   (DATA(J), J = 2, 4)        GO TO 100      ENDIF      IF (KTYPE .EQ. 16 .AND. INT(DATA(2)) .EQ. 14) THEN        WRITE (NOUT,981) ILIMO, NTYPE, ILIM, LABEL, ILIM,     1                   DATA(2), DATA(3)        GO TO 100      ENDIFC      DO 10 J = 1, 30   10 CHART(J) = BLANK      IF (NTYPE .LT. 0) GO TO 40      IF (NTYPE .GT. 37 .AND. NTYPE .LT. 50) GO TO 40      IF (NTYPE .GE. 55) GO TO 40C      IF (NTYPE .LE. 36) THEN        KV = NV(NTYPE)        IF (KV .LT. 0) KV = NWORD - 1      ENDIF      IF (NTYPE .GE. 50) KV = NVT(NTYPE - 49)      IF (KV .EQ. 0) GO TO 40      LV = 0      LPV = 0C      DO 30 JV = 1, KV      K = IABS(VARY(JV+1))      IF (K .GE. 99) K = 0      IF (VARY(JV+1) .GE. 0) GO TO 20      LV = LV + 1      CHAR(LV) = MINUS   20 LV = LV + 1      IF (K .GT. 1) LPV = LV   30 CHAR(LV) = TABLE(K+1)C      IF (KTYPE .EQ. 12 .AND. LPV .GT. 12) THEN        WRITE (NOUT,945) ILIMO, NTYPE, CHART, ILIM, LABEL, ILIM,     1                   (DATA(J), J = 2, NWORD), SEMI        GO TO 100      ENDIFC   40 IF (NWORD .LE. 1) THEN        WRITE (NOUT,960) ILIMO, NTYPE, CHARS, ILIM, LABEL, ILIM        GO TO 100      ENDIF      IF (KTYPE .EQ. 10) THEN        DATA2 = DATA(2)        DATA2 = FLOAT(IDATA2)        DATA3 = DATA(3)        DATA3 = FLOAT(IDATA3)        WRITE (NOUT,940) ILIMO, NTYPE, CHARS, ILIM, LABEL, ILIM,     1                   BLANK, DATA2, BLANK, DATA3, BLANK, DATA(4),     2                   BLANK, DATA(5), SEMI        GO TO 100      ENDIF      IF (KTYPE .EQ. 4 .AND. (DATA(4) .LE. -10000.     1    .OR. DATA(4) .GE. 100000.)) THEN        WRITE (NOUT,942) ILIMO, NTYPE, CHARS, ILIM, LABEL, ILIM,     1                   (DATA(J), J = 2, 4), SEMI      ELSE        WRITE (NOUT,940) ILIMO, NTYPE, CHARS, ILIM, LABEL, ILIM,     1                 (BLANK, DATA(J), J = 2, NWORD), SEMI      ENDIF      GO TO 100C  100 CONTINUE      RETURNC  940 FORMAT (1H ,A1,I4,'.',12A1,1X,A1,A4,A1,1X,A1,8(F11.5,A1)/     1       (28X,8(F11.5,A1)))  942 FORMAT (1H ,A1,I4,'.',12A1,1X,A1,A4,A1,1X,2F12.5,E13.5,A1)  945 FORMAT (1H ,A1,I4,'.',30A1,1X,A1,A4,A1,7X,6(F12.5)/     1       /27X,8F12.5/27X,F12.5,A1)  960 FORMAT (1H ,A1,I4,'.',12A1,1X,A1,A4,A1,1X,1H;)  970 FORMAT (1H ,A1,A1,A4,A1,2H (,29A4,A1)  980 FORMAT (1H ,A1,I4,'.',13X,A1,A4,A1,1X,F12.5,E12.4,F12.5,';')  981 FORMAT (1H ,A1,I4,'.',A1,A4,A1,1X,F12.5,I12,';')      END